sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    if (isLoading || newValue == '')
        return;

    // Replace 3 with your Closed Complete value if different
    if (newValue != '3')
        return;

    var ga = new GlideAjax('RITMValidationAjax');
    ga.addParam('sysparm_name', 'shouldShowBanner');
    ga.addParam('sysparm_ritm_sys_id', g_form.getUniqueValue());

    ga.getXMLAnswer(function(answer) {
        if (answer) {
            g_form.addInfoMessage(
                "<b>⚠ Reminder</b><br>"
                + "This Requested Item has a Parent Incident and a Catalog Task. "
                + "Before closing the RITM, please verify that:"
                + "<ul>"
                + "<li>The Parent Incident is resolved.</li>"
                + "<li>The related Catalog Task has been closed.</li>"
                + "</ul>"
            );

        }

    });

}
